const ipfsPath=u=>{const value=String(u||'').trim();if(!value)return '';if(value.startsWith('ipfs://')){const path=value.slice(7);return path.startsWith('ipfs/')?path.slice(5):path}if(value.startsWith('https://')||value.startsWith('http://')){try{const path=new URL(value).pathname;const marker='/ipfs/';const index=path.indexOf(marker);return index>=0?path.slice(index+marker.length):''}catch{return ''}}return value};
const gateway=u=>{const value=String(u||'').trim();if(!value)return '';if(value.startsWith('ipfs://'))return 'https://dweb.link/ipfs/'+ipfsPath(value);if(value.startsWith('ar://'))return 'https://arweave.net/'+value.slice(5);return value};
const ipfsGateways=u=>{const path=ipfsPath(u);return path?['https://dweb.link/ipfs/'+path,'https://cloudflare-ipfs.com/ipfs/'+path,'https://ipfs.io/ipfs/'+path]:[gateway(u)]};
function retryArtwork(e,uri){const image=e.currentTarget;const urls=ipfsGateways(uri);const next=Number(image.dataset.gatewayIndex||0)+1;if(next<urls.length){image.dataset.gatewayIndex=String(next);image.src=urls[next]}else{image.style.display='none'}}
async function logs(address,topic,latest){const base=explorer.replace(/\/$/,'')+'/api/v2/addresses/'+address+'/logs';let out=[],cursor=null;for(let page=0;page<100;page++){const params=new URLSearchParams({topic});if(cursor)for(const [k,v] of Object.entries(cursor))params.set(k,String(v));const response=await fetch(base+'?'+params.toString(),{headers:{Accept:'application/json'}});if(!response.ok)throw Error('Explorer history API returned HTTP '+response.status);const body=await response.json();for(const item of body.items||[]){if(!item.topics?.length)continue;out.push({topics:item.topics,data:item.data||'0x',transactionHash:item.transaction_hash,blockNumber:Number(item.block_number)})}cursor=body.next_page_params;if(!cursor||!(body.items||[]).length)break}return out}
async function meta(uri){try{const raw=String(uri||'').trim();if(raw.startsWith('data:')){const payload=raw.slice(raw.indexOf(',')+1);const decoded=raw.includes(';base64,')?atob(payload):decodeURIComponent(payload);return JSON.parse(decoded)}for(const url of ipfsGateways(raw)){try{const r=await fetch(url,{headers:{Accept:'application/json'}});if(r.ok){const value=await r.json();if(value&&typeof value==='object')return value}}catch{}}return null}catch{return null}}
