   for(const c of cols){try{const nft=new Contract(c.address,N,provider);for(const l of await logs(c.address,nft.interface.getEvent('NFTMinted').topicHash,latest)){try{const p=nft.interface.parseLog(l);acts.push({label:'NFT #'+p.args.tokenId+' minted',by:p.args.to,tx:l.transactionHash,block:l.blockNumber})}catch{}}}catch(e){console.warn('NFT mint history unavailable',c.address,e)}}
    setCollections(cols);
   try{for(const l of await logs(A.market,market.interface.getEvent('NFTListed').topicHash,latest)){const p=market.interface.parseLog(l);acts.push({label:'NFT listed',by:p.args.seller,tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Listing activity logs unavailable',e)}
   try{const next=Number(await market.nextListingId());for(let id=1;id<next;id++){try{const v=await market.listings(id);if(v[4]){const n=items.find(x=>x.collection.toLowerCase()===v[0].toLowerCase()&&x.id===v[1].toString());ls.push({id:String(id),collection:v[0],token:v[1].toString(),seller:v[2],price:v[3],name:n?.name||'NFT #'+v[1],image:n?.image||''})}}catch(e){console.warn('Listing read failed',id,e)}}}catch(e){console.warn('On-chain listing count unavailable',e)}
   try{for(const l of await logs(A.auction,auction.interface.getEvent('AuctionCreated').topicHash,latest)){const p=auction.interface.parseLog(l);acts.push({label:'Auction #'+p.args.auctionId+' created',by:p.args.seller,tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Auction activity logs unavailable',e)}
   try{const next=Number(await auction.nextAuctionId()),now=Math.floor(Date.now()/1000);for(let id=1;id<next;id++){try{const v=await auction.auctions(id);if(v[2]!=='0x0000000000000000000000000000000000000000'&&!v[7]&&!v[8]){const n=items.find(x=>x.collection.toLowerCase()===v[0].toLowerCase()&&x.id===v[1].toString());as.push({id:String(id),collection:v[0],token:v[1].toString(),seller:v[2],reserve:v[3],bid:v[4],bidder:v[5],end:v[6],finalized:v[7],claimed:v[8],name:n?.name||'NFT #'+v[1],image:n?.image||''})}}catch(e){console.warn('Auction read failed',id,e)}}}catch(e){console.warn('On-chain auction count unavailable',e)}
   try{for(const l of await logs(A.market,market.interface.getEvent('NFTSold').topicHash,latest)){const p=market.interface.parseLog(l);acts.push({label:'NFT sold for '+fmt(p.args.price),by:p.args.buyer,tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Sale logs unavailable',e)}
    try{for(const l of await logs(A.market,market.interface.getEvent('ListingCancelled').topicHash,latest)){const p=market.interface.parseLog(l);acts.push({label:'Listing #'+p.args.listingId+' cancelled',by:'',tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Listing cancellation history unavailable',e)}
    try{for(const l of await logs(A.auction,auction.interface.getEvent('BidPlaced').topicHash,latest)){const p=auction.interface.parseLog(l);acts.push({label:'Bid placed · '+fmt(p.args.amount),by:p.args.bidder,tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Bid history unavailable',e)}
    try{for(const l of await logs(A.auction,auction.interface.getEvent('AuctionFinalized').topicHash,latest)){const p=auction.interface.parseLog(l);acts.push({label:'Auction #'+p.args.auctionId+' finalized · '+fmt(p.args.winningBid),by:p.args.winner,tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Auction finalization history unavailable',e)}
    try{for(const l of await logs(A.auction,auction.interface.getEvent('NFTClaimed').topicHash,latest)){const p=auction.interface.parseLog(l);acts.push({label:'Auction #'+p.args.auctionId+' NFT claimed',by:p.args.winner,tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Auction claim history unavailable',e)}
    try{for(const l of await logs(A.auction,auction.interface.getEvent('AuctionCancelled').topicHash,latest)){const p=auction.interface.parseLog(l);acts.push({label:'Auction #'+p.args.auctionId+' cancelled',by:'',tx:l.transactionHash,block:l.blockNumber})}}catch(e){console.warn('Auction cancellation history unavailable',e)}
   acts.sort((x,y)=>y.block-x.block);setNfts(items);setListings(ls);setAuctions(as);setActivity(acts);let minted=0;for(const c of cols){try{minted+=Number(await new Contract(c.address,N,provider).totalMinted())}catch{}}setStats([minted,cols.length,ls.length,as.filter(a=>Number(a.end)>Math.floor(Date.now()/1000)).length]);setNotice('NFTs loaded from on-chain collection records.');
